import { useEffect, useRef, useState } from 'react'
import { getDocument, type PDFDocumentProxy } from 'pdfjs-dist'
import { Loader2 } from 'lucide-react'
import '@/lib/case-pdf' // sets the pdf.js worker

/**
 * One page of the uploaded PDF, rendered by pdf.js exactly as it prints:
 * layout, tables and the MRI images included. Fits the column's width and
 * never grows taller than 70% of the window; sharp on high-DPI screens.
 */
export function PdfPage({ url, page }: { url: string; page: number }) {
  const box = useRef<HTMLDivElement>(null)
  const canvas = useRef<HTMLCanvasElement>(null)
  const [doc, setDoc] = useState<PDFDocumentProxy | null>(null)
  const [width, setWidth] = useState(0)
  const [ready, setReady] = useState(false)

  useEffect(() => {
    const task = getDocument({ url })
    task.promise.then(setDoc, () => setDoc(null))
    return () => {
      setDoc(null)
      void task.destroy()
    }
  }, [url])

  useEffect(() => {
    const el = box.current
    if (!el) return
    const ro = new ResizeObserver(([e]) => setWidth(Math.floor(e.contentRect.width)))
    ro.observe(el)
    return () => ro.disconnect()
  }, [])

  useEffect(() => {
    const c = canvas.current
    if (!doc || !c || !width) return
    let cancelled = false
    let render: { cancel: () => void } | null = null
    setReady(false)
    void doc.getPage(page + 1).then((p) => {
      if (cancelled) return
      const base = p.getViewport({ scale: 1 })
      const fit = Math.min(width / base.width, (window.innerHeight * 0.7) / base.height)
      const dpr = window.devicePixelRatio || 1
      const vp = p.getViewport({ scale: fit * dpr })
      c.width = Math.floor(vp.width)
      c.height = Math.floor(vp.height)
      c.style.width = `${Math.floor(base.width * fit)}px`
      c.style.height = `${Math.floor(base.height * fit)}px`
      const task = p.render({ canvas: c, viewport: vp })
      render = task
      task.promise.then(() => !cancelled && setReady(true), () => {})
    })
    return () => {
      cancelled = true
      render?.cancel()
    }
  }, [doc, page, width])

  return (
    <div ref={box} className="relative flex min-h-48 justify-center rounded-lg border bg-muted/40 p-2">
      <canvas ref={canvas} className="rounded-sm bg-white shadow-sm" aria-label={`PDF page ${page + 1}`} role="img" />
      {!ready ? <Loader2 className="absolute top-1/2 left-1/2 size-5 -translate-1/2 animate-spin text-muted-foreground" aria-hidden /> : null}
    </div>
  )
}

