import { useEffect, useRef, useState } from 'react'
import { getDocument, type PDFDocumentProxy } from 'pdfjs-dist'
import { Loader2 } from 'lucide-react'
import '@/lib/case-pdf' // sets the pdf.js worker

/**
 * One page of the uploaded PDF, rendered by pdf.js exactly as it prints:
 * layout, tables and the MRI images included. Fills the card's width and
 * takes whatever height the page needs, so the whole page is always visible.
 */
export function PdfPage({ bytes, page }: { bytes: Uint8Array; page: number }) {
  const box = useRef<HTMLDivElement>(null)
  const canvas = useRef<HTMLCanvasElement>(null)
  const [doc, setDoc] = useState<PDFDocumentProxy | null>(null)
  const [width, setWidth] = useState(0)
  const [ready, setReady] = useState(false)
  const [error, setError] = useState('')

  useEffect(() => {
    // pdf.js hands the buffer to its worker and detaches it, so give it a copy.
    const task = getDocument({ data: bytes.slice() })
    task.promise.then(setDoc, (e: unknown) => {
      console.error('[PdfPage] load failed', e)
      setError('Couldn’t open this PDF for preview.')
    })
    return () => {
      setDoc(null)
      void task.destroy()
    }
  }, [bytes])

  useEffect(() => {
    const el = box.current
    if (!el) return
    const ro = new ResizeObserver(([e]) => setWidth(Math.floor(e.contentRect.width)))
    ro.observe(el)
    return () => ro.disconnect()
  }, [])

  useEffect(() => {
    const c = canvas.current
    if (!doc || !c || !width) return
    let cancelled = false
    let render: { cancel: () => void } | null = null
    setReady(false)
    doc
      .getPage(page + 1)
      .then((p) => {
        if (cancelled) return
        const base = p.getViewport({ scale: 1 })
        const fit = width / base.width
        const vp = p.getViewport({ scale: fit * (window.devicePixelRatio || 1) })
        c.width = Math.floor(vp.width)
        c.height = Math.floor(vp.height)
        c.style.height = `${Math.round(base.height * fit)}px`
        const task = p.render({ canvas: c, viewport: vp })
        render = task
        return task.promise.then(() => !cancelled && setReady(true))
      })
      .catch((e: unknown) => {
        if (cancelled || (e instanceof Error && e.name === 'RenderingCancelledException')) return
        console.error('[PdfPage] render failed', e)
        setError(`Couldn’t draw page ${page + 1}.`)
      })
    return () => {
      cancelled = true
      render?.cancel()
    }
  }, [doc, page, width])

  return (
    <div ref={box} className="relative w-full">
      <canvas
        ref={canvas}
        className={`block w-full rounded-md bg-white ring-1 ring-border ${ready ? '' : 'min-h-96'}`}
        aria-label={`PDF page ${page + 1}`}
        role="img"
      />
      {error ? (
        <p className="absolute inset-0 grid place-items-center text-xs text-destructive" role="alert">{error}</p>
      ) : !ready ? (
        <Loader2 className="absolute top-1/2 left-1/2 size-5 -translate-1/2 animate-spin text-muted-foreground" aria-hidden />
      ) : null}
    </div>
  )
}

